/**
 ******************************************************************************
 * @file    test_fx_store.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant.
 * @brief   Host tests for fx_store.c: effect-file paths, the names DELETE
 *          accepts, the hash and the effect-file header with its tag.
 *
 * Groups:
 *   1. Folders and paths: six short folder names, FX/<FOLDER>/<NAME>.WAV
 *      and .TMP, the longest path fits its buffer
 *   2. Names DELETE accepts: only what the File list could show
 *   3. Delete paths: the recording and its 12 effect / .TMP paths, in order
 *   4. Effect numbers: Jack's copy agrees with the folder table
 *   5. Hash: FNV-1a known vectors, head and tail both count
 *   6. Header and tag: 68 bytes that every WAV reader accepts, the tag
 *      round trip, and each tag field on its own makes a file stale
 * Pure logic: no card, no fake needed.
 ******************************************************************************/
#include "unity.h"
#include "fx_store.h"
#include "wav_storage.h"
#include <string.h>

void setUp(void) {}
void tearDown(void) {}

/* ---------- 1. Folders and paths ---------- */

void test_folder_names_are_six_and_short(void)
{
    for (uint8_t e = 1U; e <= FXS_EFFECT_COUNT; e++)
    {
        const char *folder = fx_folder(e);
        TEST_ASSERT_NOT_NULL(folder);
        TEST_ASSERT_TRUE(strlen(folder) >= 1U);
        TEST_ASSERT_TRUE(strlen(folder) <= FXS_BASE_MAX_CHARS);       /* an 8.3 folder name */
        for (uint8_t other = 1U; other < e; other++)
        {
            TEST_ASSERT_TRUE(strcmp(folder, fx_folder(other)) != 0);   /* all different */
        }
    }
    TEST_ASSERT_NULL(fx_folder(FXS_EFFECT_NONE));
    TEST_ASSERT_NULL(fx_folder(FXS_EFFECT_COUNT + 1U));
}

void test_each_effect_file_lives_in_its_own_fx_folder(void)
{
    static const char *const want[FXS_EFFECT_COUNT] = {
        "FX/AUTOTUNE/REC05.WAV", "FX/PITCHUP/REC05.WAV", "FX/PITCHDN/REC05.WAV",
        "FX/ROBOT/REC05.WAV", "FX/ECHO/REC05.WAV", "FX/REVERB/REC05.WAV"
    };
    char path[FXS_PATH_LEN];
    for (uint8_t e = 1U; e <= FXS_EFFECT_COUNT; e++)
    {
        TEST_ASSERT_TRUE(fx_file_path(e, "REC05.WAV", false, path, sizeof(path)));
        TEST_ASSERT_EQUAL_STRING(want[e - 1U], path);
    }
    TEST_ASSERT_TRUE(fx_dir_path(FXS_EFFECT_ECHO, path, sizeof(path)));
    TEST_ASSERT_EQUAL_STRING("FX/ECHO", path);
    TEST_ASSERT_FALSE(fx_file_path(FXS_EFFECT_NONE, "REC05.WAV", false, path, sizeof(path)));
    TEST_ASSERT_EQUAL_STRING("", path);
}

void test_tmp_path_swaps_the_extension(void)
{
    char path[FXS_PATH_LEN];
    TEST_ASSERT_TRUE(fx_file_path(FXS_EFFECT_ROBOT, "REC05.WAV", true, path, sizeof(path)));
    TEST_ASSERT_EQUAL_STRING("FX/ROBOT/REC05.TMP", path);
    TEST_ASSERT_TRUE(fx_file_path(FXS_EFFECT_ROBOT, "take1.wav", true, path, sizeof(path)));
    TEST_ASSERT_EQUAL_STRING("FX/ROBOT/take1.TMP", path);
}

void test_the_longest_path_fits_its_buffer_and_a_short_buffer_is_refused(void)
{
    char path[FXS_PATH_LEN];
    TEST_ASSERT_TRUE(fx_file_path(FXS_EFFECT_AUTOTUNE, "ABCDEFGH.WAV", false, path, sizeof(path)));
    TEST_ASSERT_EQUAL_STRING("FX/AUTOTUNE/ABCDEFGH.WAV", path);
    TEST_ASSERT_EQUAL_UINT32(24U, (uint32_t)strlen(path));

    char small[24];                                   /* one byte short for the NUL */
    TEST_ASSERT_FALSE(fx_file_path(FXS_EFFECT_AUTOTUNE, "ABCDEFGH.WAV", false, small, sizeof(small)));
    TEST_ASSERT_EQUAL_STRING("", small);
}

/* ---------- 2. Names DELETE accepts ---------- */

void test_accepts_the_names_the_list_shows(void)
{
    TEST_ASSERT_TRUE(fx_name_ok("REC05.WAV"));
    TEST_ASSERT_TRUE(fx_name_ok("rec05.wav"));
    TEST_ASSERT_TRUE(fx_name_ok("A.WAV"));
    TEST_ASSERT_TRUE(fx_name_ok("ABCDEFGH.WAV"));
}

void test_rejects_names_with_a_slash(void)
{
    TEST_ASSERT_FALSE(fx_name_ok("FX/ECHO"));
    TEST_ASSERT_FALSE(fx_name_ok("FX/E.WAV"));
    TEST_ASSERT_FALSE(fx_name_ok("A\\B.WAV"));
}

void test_rejects_long_names(void)
{
    TEST_ASSERT_FALSE(fx_name_ok("ABCDEFGHI.WAV"));    /* 9 characters before the dot */

    /* A 13-byte name field with no NUL in it. */
    char full[FXS_NAME_LEN + 1U];
    memset(full, 'A', sizeof(full));
    memcpy(&full[FXS_NAME_LEN - 4U], ".WAV", 4U);
    TEST_ASSERT_FALSE(fx_name_ok(full));
}

void test_rejects_names_that_are_not_wav(void)
{
    TEST_ASSERT_FALSE(fx_name_ok("A.TXT"));
    TEST_ASSERT_FALSE(fx_name_ok("REC05.WA"));
    TEST_ASSERT_FALSE(fx_name_ok(".WAV"));              /* nothing before the dot */
    TEST_ASSERT_FALSE(fx_name_ok("A.B.WAV"));           /* two dots */
    TEST_ASSERT_FALSE(fx_name_ok("FX"));                /* the effect folder itself */
    TEST_ASSERT_FALSE(fx_name_ok(""));
    TEST_ASSERT_FALSE(fx_name_ok(NULL));
}

void test_rejects_a_leading_underscore(void)
{
    TEST_ASSERT_FALSE(fx_name_ok("_X.WAV"));           /* how a Mac "._X.WAV" reads without long names */
}

/* ---------- 3. Delete paths ---------- */

void test_delete_paths_are_thirteen(void)
{
    static const char *const want[FXS_DELETE_PATHS] = {
        "REC05.WAV",
        "FX/AUTOTUNE/REC05.WAV", "FX/AUTOTUNE/REC05.TMP",
        "FX/PITCHUP/REC05.WAV",  "FX/PITCHUP/REC05.TMP",
        "FX/PITCHDN/REC05.WAV",  "FX/PITCHDN/REC05.TMP",
        "FX/ROBOT/REC05.WAV",    "FX/ROBOT/REC05.TMP",
        "FX/ECHO/REC05.WAV",     "FX/ECHO/REC05.TMP",
        "FX/REVERB/REC05.WAV",   "FX/REVERB/REC05.TMP"
    };
    char path[FXS_PATH_LEN];
    for (uint8_t i = 0U; i < FXS_DELETE_PATHS; i++)
    {
        TEST_ASSERT_TRUE(fx_delete_path(i, "REC05.WAV", path, sizeof(path)));
        TEST_ASSERT_EQUAL_STRING(want[i], path);
    }
    TEST_ASSERT_FALSE(fx_delete_path(FXS_DELETE_PATHS, "REC05.WAV", path, sizeof(path)));
    TEST_ASSERT_FALSE(fx_delete_path(0U, "FX/ECHO", path, sizeof(path)));
}

/* ---------- 4. Effect numbers ---------- */

void test_effect_numbers_are_one_to_six(void)
{
    TEST_ASSERT_EQUAL_UINT8(0U, FXS_EFFECT_NONE);
    TEST_ASSERT_EQUAL_UINT8(6U, FXS_EFFECT_COUNT);
    TEST_ASSERT_EQUAL_STRING("AUTOTUNE", fx_folder(FXS_EFFECT_AUTOTUNE));
    TEST_ASSERT_EQUAL_STRING("PITCHUP", fx_folder(FXS_EFFECT_PITCHUP));
    TEST_ASSERT_EQUAL_STRING("PITCHDN", fx_folder(FXS_EFFECT_PITCHDN));
    TEST_ASSERT_EQUAL_STRING("ROBOT", fx_folder(FXS_EFFECT_ROBOT));
    TEST_ASSERT_EQUAL_STRING("ECHO", fx_folder(FXS_EFFECT_ECHO));
    TEST_ASSERT_EQUAL_STRING("REVERB", fx_folder(FXS_EFFECT_REVERB));
    TEST_ASSERT_EQUAL_UINT8(6U, FXS_EFFECT_REVERB);
}

/* ---------- 5. Hash ---------- */

void test_hash_matches_the_fnv1a_known_vectors(void)
{
    TEST_ASSERT_EQUAL_HEX32(0x811C9DC5U, fx_hash_begin());                         /* "" */
    TEST_ASSERT_EQUAL_HEX32(0xE40C292CU, fx_hash_add(fx_hash_begin(), (const uint8_t *)"a", 1U));
    TEST_ASSERT_EQUAL_HEX32(0xBF9CF968U, fx_hash_add(fx_hash_begin(), (const uint8_t *)"foobar", 6U));
}

void test_hash_covers_head_and_tail(void)
{
    uint8_t head[FXS_HASH_PART_BYTES];
    uint8_t tail[FXS_HASH_PART_BYTES];
    for (size_t i = 0U; i < FXS_HASH_PART_BYTES; i++)
    {
        head[i] = (uint8_t)(i * 7U);
        tail[i] = (uint8_t)(i * 13U);
    }
    /* Head then tail, fed in two parts, is one hash over both. */
    uint8_t both[2U * FXS_HASH_PART_BYTES];
    memcpy(both, head, sizeof(head));
    memcpy(&both[FXS_HASH_PART_BYTES], tail, sizeof(tail));
    const uint32_t two_parts = fx_hash_add(fx_hash_add(fx_hash_begin(), head, sizeof(head)), tail, sizeof(tail));
    TEST_ASSERT_EQUAL_HEX32(fx_hash_add(fx_hash_begin(), both, sizeof(both)), two_parts);

    /* The same head with one byte of the tail changed: another hash. */
    tail[FXS_HASH_PART_BYTES - 1U] ^= 0x01U;
    const uint32_t other_tail = fx_hash_add(fx_hash_add(fx_hash_begin(), head, sizeof(head)), tail, sizeof(tail));
    TEST_ASSERT_TRUE(other_tail != two_parts);
}

/* ---------- 6. Header and tag ---------- */

/* The facts of a 10 s toy recording: 32 kHz, header 44 bytes, date 0. */
static fx_src_t ten_second_source(void)
{
    fx_src_t src;
    memset(&src, 0, sizeof(src));
    src.size = 640044U;
    src.hash = 0x12345678U;
    src.rate = 32000U;
    src.data_offset = 44U;
    src.data_size = 640000U;
    src.channels = 1U;
    src.bits = 16U;
    src.playable = true;
    src.renderable = true;
    return src;
}

void test_header_is_68_bytes_and_parses_as_a_48k_mono_wav(void)
{
    fx_src_t src = ten_second_source();
    fx_tag_t tag;
    fx_tag_from_src(&tag, 1U, FXS_EFFECT_ECHO, &src);
    uint8_t header[FXS_HEADER_BYTES];
    const uint32_t data_bytes = 960000U;               /* 10 s at 48 kHz */
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_build_header(&tag, data_bytes, header, sizeof(header)));
    TEST_ASSERT_EQUAL_MEMORY("RIFF", &header[0], 4U);
    TEST_ASSERT_EQUAL_MEMORY("bjfx", &header[36], 4U);
    TEST_ASSERT_EQUAL_MEMORY("data", &header[60], 4U);

    /* Jack's own parser (it skips the unknown "bjfx" chunk) reads it as a
     * plain 48 kHz mono 16-bit WAV whose samples start at byte 68. */
    wav_header_t wav;
    TEST_ASSERT_EQUAL(STORAGE_OK, wav_parse_header(header, sizeof(header), FXS_HEADER_BYTES + data_bytes, &wav));
    TEST_ASSERT_EQUAL_UINT32(FXS_RATE_HZ, wav.sample_rate);
    TEST_ASSERT_EQUAL_UINT16(1U, wav.num_channels);
    TEST_ASSERT_EQUAL_UINT16(16U, wav.bits_per_sample);
    TEST_ASSERT_EQUAL_UINT32(FXS_HEADER_BYTES, wav.data_offset);
    TEST_ASSERT_EQUAL_UINT32(data_bytes, wav.data_size);
    TEST_ASSERT_FALSE(wav.data_size_clamped);

    uint8_t small[FXS_HEADER_BYTES - 1U];
    TEST_ASSERT_EQUAL(STORAGE_INVALID_ARG, fx_build_header(&tag, data_bytes, small, sizeof(small)));
}

void test_tag_round_trips_through_the_header(void)
{
    fx_src_t src = ten_second_source();
    src.rate = 48000U;
    src.fdate = 0x5B3AU;
    src.ftime = 0x6C21U;
    fx_tag_t written;
    fx_tag_from_src(&written, 7U, FXS_EFFECT_REVERB, &src);
    TEST_ASSERT_EQUAL_UINT8(1U, written.src_48k);

    uint8_t header[FXS_HEADER_BYTES];
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_build_header(&written, 1000U, header, sizeof(header)));
    fx_tag_t read;
    TEST_ASSERT_EQUAL(STORAGE_OK, fx_parse_tag(header, sizeof(header), &read));
    TEST_ASSERT_TRUE(fx_tag_matches(&read, &written));
    TEST_ASSERT_EQUAL_UINT32(src.size, read.src_size);
    TEST_ASSERT_EQUAL_UINT32(src.hash, read.src_hash);
    TEST_ASSERT_EQUAL_UINT16(7U, read.version);
    TEST_ASSERT_EQUAL_UINT8(FXS_EFFECT_REVERB, read.effect);
    TEST_ASSERT_EQUAL_UINT16(0x5B3AU, read.src_fdate);
    TEST_ASSERT_EQUAL_UINT16(0x6C21U, read.src_ftime);
}

void test_a_wav_without_a_tag_is_not_an_effect_file(void)
{
    uint8_t plain[WAV_HEADER_SIZE];
    TEST_ASSERT_EQUAL(STORAGE_OK, wav_build_header(32000U, 16U, 1U, 100U, plain, sizeof(plain)));
    fx_tag_t tag;
    TEST_ASSERT_EQUAL(STORAGE_NOT_FOUND, fx_parse_tag(plain, sizeof(plain), &tag));

    uint8_t junk[FXS_HEADER_BYTES];
    memset(junk, 0x55, sizeof(junk));
    TEST_ASSERT_EQUAL(STORAGE_CORRUPT, fx_parse_tag(junk, sizeof(junk), &tag));
}

/* A tag made from the 10 s source, and a copy with one field changed. */
static void tag_pair(fx_tag_t *made, fx_tag_t *now)
{
    fx_src_t src = ten_second_source();
    fx_tag_from_src(made, 1U, FXS_EFFECT_ECHO, &src);
    *now = *made;
    TEST_ASSERT_TRUE(fx_tag_matches(made, now));
}

void test_match_fails_on_version(void)
{
    fx_tag_t made, now;
    tag_pair(&made, &now);
    now.version = 2U;                                  /* the echo was changed since */
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

void test_match_fails_on_effect(void)
{
    fx_tag_t made, now;
    tag_pair(&made, &now);
    now.effect = FXS_EFFECT_ROBOT;
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

void test_match_fails_on_size(void)
{
    fx_tag_t made, now;
    tag_pair(&made, &now);
    now.src_size += 2U;                                /* a longer recording under the same name */
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

void test_match_fails_on_hash(void)
{
    fx_tag_t made, now;
    tag_pair(&made, &now);
    now.src_hash ^= 1U;                                /* REC05 recorded again: other microphone noise */
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

void test_match_fails_on_timestamp(void)
{
    fx_tag_t made, now;
    tag_pair(&made, &now);
    now.src_fdate = 0x5B3AU;                           /* a PC copied another file over it */
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
    tag_pair(&made, &now);
    now.src_ftime = 0x0001U;
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

void test_match_fails_on_the_tail(void)
{
    /* Two sources with the same size and the same first 512 bytes (both
     * start with silence) that differ only near their end. The test
     * makes both hashes itself, so it checks the hash and the compare,
     * not that fxj_fingerprint reads the tail (no test checks that yet). */
    static uint8_t first[2048];
    static uint8_t second[2048];
    memset(first, 0, sizeof(first));
    memset(second, 0, sizeof(second));
    second[2040] = 1U;
    fx_src_t a = ten_second_source();
    fx_src_t b = ten_second_source();
    a.hash = fx_hash_add(fx_hash_add(fx_hash_begin(), first, 512U), &first[2048U - 512U], 512U);
    b.hash = fx_hash_add(fx_hash_add(fx_hash_begin(), second, 512U), &second[2048U - 512U], 512U);
    fx_tag_t made, now;
    fx_tag_from_src(&made, 1U, FXS_EFFECT_ECHO, &a);
    fx_tag_from_src(&now, 1U, FXS_EFFECT_ECHO, &b);
    TEST_ASSERT_FALSE(fx_tag_matches(&made, &now));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_folder_names_are_six_and_short);
    RUN_TEST(test_each_effect_file_lives_in_its_own_fx_folder);
    RUN_TEST(test_tmp_path_swaps_the_extension);
    RUN_TEST(test_the_longest_path_fits_its_buffer_and_a_short_buffer_is_refused);
    RUN_TEST(test_accepts_the_names_the_list_shows);
    RUN_TEST(test_rejects_names_with_a_slash);
    RUN_TEST(test_rejects_long_names);
    RUN_TEST(test_rejects_names_that_are_not_wav);
    RUN_TEST(test_rejects_a_leading_underscore);
    RUN_TEST(test_delete_paths_are_thirteen);
    RUN_TEST(test_effect_numbers_are_one_to_six);
    RUN_TEST(test_hash_matches_the_fnv1a_known_vectors);
    RUN_TEST(test_hash_covers_head_and_tail);
    RUN_TEST(test_header_is_68_bytes_and_parses_as_a_48k_mono_wav);
    RUN_TEST(test_tag_round_trips_through_the_header);
    RUN_TEST(test_a_wav_without_a_tag_is_not_an_effect_file);
    RUN_TEST(test_match_fails_on_version);
    RUN_TEST(test_match_fails_on_effect);
    RUN_TEST(test_match_fails_on_size);
    RUN_TEST(test_match_fails_on_hash);
    RUN_TEST(test_match_fails_on_timestamp);
    RUN_TEST(test_match_fails_on_the_tail);
    return UNITY_END();
}
